import{cellOf,isEmptyValue,numericValue}from'./properties.js';
export const AGGREGATE_KINDS=['count','countEmpty','sum','average','min','max'];
export function aggregateValues(values,kind){
if(!AGGREGATE_KINDS.includes(kind))
throw new RangeError(`Unknown aggregate: ${String(kind)}`);
if(kind==='count')
return values.filter((value)=>!isEmptyValue(value)).length;
if(kind==='countEmpty')
return values.filter((value)=>isEmptyValue(value)).length;
let count=0;
let sum=0;
let min=Infinity;
let max=-Infinity;
for(const value of values){
const n=numericValue(value);
if(n===null)
continue;
count+=1;
sum+=n;
if(n<min)
min=n;
if(n>max)
max=n;
}
if(count===0)
return null;
const result=kind==='sum'?sum:kind==='average'?sum/count:kind==='min'?min:max;
return Number.isFinite(result)?result:null;
}
export function aggregateColumn(rows,propertyId,kind){
return aggregateValues(rows.map((row)=>cellOf(row,propertyId)),kind);
}
